/* ❌ OLD: Every item in a long list is fully laid out and painted on
   load, even the ones thousands of pixels below the viewport. For a
   10,000-item feed this means layout and paint work for the entire
   document up front — slow first render and slow scroll. */

.item {
  /* ❌ OLD: no skipping — full render cost for all items */
}

/* The browser computes layout and paint for all items eagerly;
   scrolling later only benefits because everything was already
   rendered, but the initial cost is proportional to total content. */

/* ✅ NEW: content-visibility: auto skips layout+paint for items that
   are off-screen. contain-intrinsic-size reserves their space so the
   scrollbar and layout stay stable. */

.item {
  content-visibility: auto; /* ✅ NEW: skip off-screen rendering */
  contain-intrinsic-size: auto 120px; /* ✅ NEW: remembered/estimated height */
}

/* When an item scrolls near the viewport, the engine 'unskips' it and
   renders it on demand. Initial cost is proportional to the visible
   items, not the whole 10,000-item feed. */
